// SECURE: Security configuration to protect H2 console
package com.example.security;

import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.context.annotation.Profile;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@Profile("dev")  // Only active in development profile
public class H2ConsoleSecurityConfig {

    @Bean
    public SecurityFilterChain h2ConsoleFilterChain(HttpSecurity http) throws Exception {
        http
            // ✅ Require authentication for H2 console
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/h2-console/**").hasRole("ADMIN")
                .anyRequest().authenticated()
            )

            // ✅ CSRF exemption for H2 console (frame-based UI)
            .csrf(csrf -> csrf
                .ignoringRequestMatchers("/h2-console/**")
            )

            // ✅ Allow frames from same origin (H2 console requirement)
            .headers(headers -> headers
                .frameOptions(frame -> frame.sameOrigin())
            );

        return http.build();
    }
}
```

### Tier 3: Production Hardening (20 min)

**Add profile validation and startup checks**

```java
// SECURE: Startup validation to prevent H2 in production
package com.example.config;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.context.event.ApplicationReadyEvent;
import org.springframework.context.event.EventListener;
import org.springframework.core.env.Environment;
import org.springframework.stereotype.Component;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Component
public class ProductionSecurityValidator {

    private static final Logger log = LoggerFactory.getLogger(ProductionSecurityValidator.class);

    @Value("${spring.h2.console.enabled:false}")
    private boolean h2ConsoleEnabled;

    @Value("${spring.datasource.url:}")
    private String datasourceUrl;

    private final Environment environment;

    public ProductionSecurityValidator(Environment environment) {
        this.environment = environment;
    }

    @EventListener(ApplicationReadyEvent.class)
    public void validateProductionSecurity() {
        String[] activeProfiles = environment.getActiveProfiles();
        boolean isProduction = java.util.Arrays.asList(activeProfiles).contains("prod");

        if (isProduction) {
            // ✅ Fail fast if H2 enabled in production
            if (h2ConsoleEnabled) {
                String error = "SECURITY VIOLATION: H2 console enabled in production profile";
                log.error(error);
                throw new IllegalStateException(error);
            }

            // ✅ Fail fast if H2 database in production
            if (datasourceUrl != null && datasourceUrl.contains("h2:")) {
                String error = "SECURITY VIOLATION: H2 database configured in production profile";
                log.error(error);
                throw new IllegalStateException(error);
            }

            log.info("✅ Production security validation passed");
        }
    }
}

// SECURE: Integration test
package com.example.config;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.core.env.Environment;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest
@ActiveProfiles("prod")
public class ProductionSecurityTest {

    @Autowired
    private Environment environment;

    @Autowired
    private ProductionSecurityValidator validator;

    @Test
    public void testH2DisabledInProduction() {
        String h2ConsoleEnabled = environment.getProperty("spring.h2.console.enabled");

        // ✅ H2 console must be false or not set in production
        assertTrue(h2ConsoleEnabled == null || h2ConsoleEnabled.equals("false"),
            "H2 console must be disabled in production profile");
    }

    @Test
    public void testProductionDatabaseNotH2() {
        String datasourceUrl = environment.getProperty("spring.datasource.url");

        // ✅ Production must not use H2 database
        assertFalse(datasourceUrl != null && datasourceUrl.contains("h2:"),
            "Production profile must not use H2 database");
    }
}
